<?php
require_once __DIR__.'/../includes/bootstrap.php';
if (empty($_SESSION['admin_id'])) redirect('login.php');
$pdo = db();
$notice = '';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    $token = trim((string)($_POST['cloudflare_token'] ?? ''));
    if ($token !== '' && !preg_match('/^[a-zA-Z0-9_-]{20,200}$/', $token)) {
        $error = 'Cloudflare token کی شکل درست نہیں۔ Cloudflare dashboard سے مکمل token کاپی کریں۔';
    } else {
        $stmt = $pdo->prepare('INSERT INTO site_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');
        $stmt->execute(['cloudflare_analytics_token', $token]);
        $notice = 'Analytics settings محفوظ ہو گئیں۔';
    }
}
$token = (string)($pdo->query("SELECT setting_value FROM site_settings WHERE setting_key='cloudflare_analytics_token'")->fetchColumn() ?: '');
$today = $pdo->query("SELECT COUNT(*) FROM analytics_events WHERE event_type='page_view' AND DATE(created_at)=CURDATE()")->fetchColumn();
$uniqueToday = $pdo->query("SELECT COUNT(DISTINCT visitor_hash) FROM analytics_events WHERE event_type='page_view' AND DATE(created_at)=CURDATE()")->fetchColumn();
$totalViews = $pdo->query("SELECT COUNT(*) FROM analytics_events WHERE event_type='page_view'")->fetchColumn();
$clicks = $pdo->query("SELECT event_type,COUNT(*) AS total FROM analytics_events WHERE DATE(created_at)=CURDATE() AND event_type<>'page_view' GROUP BY event_type")->fetchAll(PDO::FETCH_KEY_PAIR);
$topPages = $pdo->query("SELECT page_path,COUNT(*) AS total FROM analytics_events WHERE event_type='page_view' AND created_at >= DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY page_path ORDER BY total DESC LIMIT 8")->fetchAll();
$recentDays = $pdo->query("SELECT DATE(created_at) AS day,COUNT(*) AS views,COUNT(DISTINCT visitor_hash) AS visitors FROM analytics_events WHERE event_type='page_view' AND created_at >= DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
$maxViews = 1; foreach ($recentDays as $d) $maxViews = max($maxViews,(int)$d['views']);
