<div class="analytics-grid"><div class="analytics-stat"><span>آج کے منفرد وزٹرز</span><strong><?=number_format((int)$uniqueToday)?></strong></div><div class="analytics-stat"><span>آج کے Page Views</span><strong><?=number_format((int)$today)?></strong></div><div class="analytics-stat"><span>کل Page Views</span><strong><?=number_format((int)$totalViews)?></strong></div><div class="analytics-stat"><span>آج کے کلکس</span><strong><?=number_format(array_sum(array_map('intval',$clicks)))?></strong></div></div>
<div class="analytics-columns"><section class="analytics-panel"><h2>گزشتہ 7 دن کے وزٹرز</h2><div class="analytics-bars"><?php foreach($recentDays as $d): ?><div class="analytics-bar-row"><span><?=e(date('d M',strtotime($d['day'])))?></span><div class="analytics-bar"><i style="width:<?=round(((int)$d['views']/$maxViews)*100)?>%"></i></div><b><?=number_format((int)$d['views'])?></b></div><?php endforeach; ?><?php if(!$recentDays): ?><p class="analytics-note">ابھی ڈیٹا موجود نہیں۔ ویب سائٹ پر وزٹ آنے کے بعد یہاں رپورٹ نظر آئے گی۔</p><?php endif; ?></div></section>
<section class="analytics-panel"><h2>آج کے بٹن کلکس</h2><div class="analytics-list"><div><span>WhatsApp</span><b><?=number_format((int)($clicks['whatsapp_click']??0))?></b></div><div><span>Contact</span><b><?=number_format((int)($clicks['contact_click']??0))?></b></div><div><span>Order / Start project</span><b><?=number_format((int)($clicks['order_click']??0))?></b></div></div></section></div>
<section class="analytics-panel"><h2>مقبول صفحات — گزشتہ 30 دن</h2><div class="analytics-list"><?php foreach($topPages as $p): ?><div><span dir="ltr"><?=e($p['page_path'])?></span><b><?=number_format((int)$p['total'])?></b></div><?php endforeach; ?><?php if(!$topPages): ?><p class="analytics-note">ابھی کوئی Page View ریکارڈ نہیں ہوا۔</p><?php endif; ?></div></section>
<section class="analytics-panel analytics-setup"><h2>Cloudflare Web Analytics کنکشن</h2><p class="analytics-note">Cloudflare کا مفت Beacon ملک، ڈیوائس، ریفرر اور صفحے کی کارکردگی کی رپورٹس Cloudflare dashboard میں دکھاتا ہے۔ نیچے اس کا Site Token محفوظ کریں۔ Cloudflare Beacon خود custom button clicks ریکارڈ نہیں کرتا؛ اوپر کے کلکس ہماری ویب سائٹ کے اپنے سادہ event counter میں محفوظ ہوتے ہیں۔</p><form method="post" class="analytics-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Cloudflare Site Token<input name="cloudflare_token" value="<?=e($token)?>" placeholder="Cloudflare سے حاصل کیا گیا token" autocomplete="off"></label><button class="button button-primary">Token محفوظ کریں</button></form><p class="analytics-note">Token عوامی Beacon identifier ہے، خفیہ API key نہیں۔ اسے Cloudflare Web Analytics میں Add a site کے بعد Manage site سے کاپی کریں۔</p><p><a href="https://developers.cloudflare.com/web-analytics/get-started/" target="_blank" rel="noopener">Cloudflare کی سرکاری سیٹ اپ گائیڈ ↗</a></p></section>
